\begin{tikzpicture}[scale=1]
\draw[thick] (0,0) circle (1.6);
\fill (0,0) circle (1.5pt);
\draw[dashed] (0,0) -- (40:1.6) node[midway,above left] {$r$};
\node[below] at (0,-1.85) {$A = 64\text{ cm}^{2}$};
\end{tikzpicture}
[/tikz]

