\coordinate (P) at (0:2.4);
\coordinate (Q) at (60:2.4);
\draw[thick] (O) -- (P) node[midway,below] {$r$};
\draw[thick] (O) -- (Q);
\draw[thick] (P) arc[start angle=0,end angle=60,radius=2.4];
\pic[draw,"$60^{\circ}$",angle radius=0.55cm,angle eccentricity=2.2] {angle=P--O--Q};
\node at (1.2,-1.0) {$A = 30\text{ m}^{2}$};
\end{tikzpicture}
[/tikz]

